<?php

namespace IPE\Dev\Markdown;

/**
 * A Markdown file with sections generated by a script: pull requests must not change them.
 * The identifiers of the sections are the values of the SECTION_ constants of the subclasses.
 *
 * @internal
 */
abstract class GeneratedDocument
{
    /**
     * @return non-empty-string relative to the root directory of the project
     */
    abstract public function getFilename();

    /**
     * @return non-empty-string the script that generates the sections, relative to the root directory of the project
     */
    abstract public function getGenerator();

    /**
     * @return list<\IPE\Dev\Markdown\GeneratedDocument>
     */
    public static function getAll()
    {
        return [new Readme(), new Contributing()];
    }

    /**
     * @return list<non-empty-string>
     */
    public function getSectionIdentifiers()
    {
        $class = new \ReflectionClass($this);
        $result = [];
        foreach ($class->getConstants() as $name => $value) {
            if (strpos($name, 'SECTION_') === 0 && is_string($value) && $value !== '') {
                $result[] = $value;
            }
        }

        return $result;
    }

    /**
     * @return non-empty-string
     */
    public function getPath()
    {
        return dirname(dirname(dirname(__DIR__))) . '/' . $this->getFilename();
    }

    /**
     * @param string $contents
     *
     * @return list<string>
     */
    public static function splitLines($contents)
    {
        return explode("\n", rtrim(str_replace("\r\n", "\n", $contents), "\n"));
    }

    /**
     * @throws \RuntimeException
     *
     * @return list<string>
     */
    public function readLines()
    {
        $contents = file_get_contents($this->getPath());
        if ($contents === false) {
            throw new \RuntimeException("Failed to read {$this->getFilename()}");
        }

        return self::splitLines($contents);
    }

    /**
     * Replace the contents of all the generated sections.
     *
     * @param array<non-empty-string, list<string>> $generatedSections the keys are the identifiers of the sections
     *
     * @throws \RuntimeException
     *
     * @return bool true if the file changed
     */
    public function update(array $generatedSections)
    {
        $missing = array_diff($this->getSectionIdentifiers(), array_keys($generatedSections));
        if ($missing !== []) {
            throw new \RuntimeException("Missing the contents of these sections of {$this->getFilename()}: " . implode(', ', $missing));
        }
        $oldLines = $this->readLines();
        $lines = $oldLines;
        foreach ($generatedSections as $sectionIdentifier => $generatedLines) {
            $section = DynamicSection::extractFrom($this, $sectionIdentifier, $lines);
            if ($section === null) {
                throw new \RuntimeException("Unable to find the section {$sectionIdentifier} in {$this->getFilename()}");
            }
            $lines = $section->withGeneratedContent($generatedLines)->getDocumentLines();
        }
        if ($lines === $oldLines) {
            return false;
        }
        if (file_put_contents($this->getPath(), implode("\n", $lines) . "\n") === false) {
            throw new \RuntimeException("Failed to write {$this->getFilename()}");
        }

        return true;
    }
}
